import org.mockito.internal.verification.api.VerificationAwareInvocation;

public class Reporter {

  private static final String NOT_A_MOCK = "Argument passed to when() is not a mock!";
  private static final String NULL_WAS_PASSED_INSIDE_WHEN =
      "null passed to when() is not allowed!\n"
          + "Examples of correct usage of when():\n"
          + "    when(mock.getArticles()).thenReturn(articles);\n"
          + "    when(mock.getArticles()).thenThrow(exception);\n"
          + "    doThrow(exception).when(mock).someVoidMethod();\n"
          + "Also, if you use @Mock annotation don't miss initMocks()";

  private static final String NOT_A_MOCK_PASSED_TO_VERIFY =
      "Argument passed to verify() is of type "
          + "%s and is not a mock!\n"
          + "Make sure you place the parenthesis correctly!\n"
          + "See the examples of correct verifications:\n"
          + "    verify(mock).someMethod();\n"
          + "    verify(mock, times(10)).someMethod();\n"
          + "    verify(mock, atLeastOnce()).someMethod();";

  private static final String NULL_PASSED_TO_VERIFY =
      "Argument passed to verify() should be a mock but is null!\n"
          + "Examples of correct verifications:\n"
          + "    verify(mock).someMethod();\n"
          + "    verify(mock, times(10)).someMethod();\n"
          + "    verify(mock, atLeastOnce()).someMethod();\n"
          + "Also, if you use @Mock annotation don't miss initMocks()";

  private static final String SMART_NULL_POINTER_EXCEPTION_MESSAGE =
      "You have a NullPointerException here:\n"
          + "-> at %s\n"
          + "because this method call was *not* stubbed correctly:\n"
          + "-> at %s\n"
          + "%s";

  private Reporter() {}

  public static MockitoException notAMockPassedToVerify(Class<?> type) {
    return new NotAMockException(String.format(NOT_A_MOCK_PASSED_TO_VERIFY, type.getSimpleName()));
  }

  public static MockitoException nullPassedToVerify() {
    return new NullInsteadOfMockException(NULL_PASSED_TO_VERIFY);
  }

  public static MockitoException notAMockPassedToWhenMethod() {
    return new NotAMockException(NOT_A_MOCK);
  }

  public static MockitoException nullPassedToWhenMethod() {
    return new NullInsteadOfMockException(NULL_WAS_PASSED_INSIDE_WHEN);
  }

  public static MockitoException missingMethodInvocation() {
    return new MissingMethodInvocationException(
        join(
            "when() requires an argument which has to be 'a method call on a mock'.",
            "For example:",
            "    when(mock.getArticles()).thenReturn(articles);",
            "Or 'a static method call on a prepared mock', for example:",
            "    prepareForTest(StaticService.class);",
            "    when(StaticService.className()).thenReturn(\"mocked\");",
            "Also, this error might show up because:",
            "1. you stub either of: final/private/equals()/hashCode() methods.",
            "   Those methods *cannot* be stubbed/verified.",
            "2. inside when() you don't call method on mock but on some other object."));

  }

  public static MockitoException unfinishedStubbing() {
    return new UnfinishedStubbingException();
  }

  public static MockitoException unfinishedVerificationException(Location location) {
    return new UnfinishedVerificationException(
        join(
            "Missing method call for verify(mock) here:",
            location,
